WITH history AS (SELECT DATE_TRUNC('DAY', "EVENT_DATE") AS period, COUNT(*) AS cnt FROM "FAKE_PROJECT"."DATASET"."ORDERS" WHERE "EVENT_DATE" >= '2026-05-01'::DATE - INTERVAL '28 DAY' AND "EVENT_DATE" < '2026-05-01'::DATE GROUP BY period) SELECT MIN(cnt) AS min_cnt, MAX(cnt) AS max_cnt, COUNT(*) AS n FROM history